    "isRequired": "No",
    "cdmDatatype": "integer",
    "userGuidance": "The count of grouped DRUG_EXPOSURE records that were included in the DRUG_ERA row",
    "etlConventions": "NA",
    "isPrimaryKey": "No",
    "isForeignKey": "No",
    "fkTableName": "NA",
